    offshore_tuition_fee = '',
    entry_requirements = '<div class="section--l section--narrow section rich-text elevator__target" data-elevator-title="Entry requirements" data-student-type="domestic" id="entry-requirements"> <div class="section__content"> <h2>Entry requirements</h2> <details class="accordion accordion--divided" data-once="webform-details-save" data-student-type="domestic"><summary class="accordion__toggle" data-once="webform-details-summary-save" id="accordion-admission-criteria--3"><h3> Admission criteria </h3><span class="button button--small button--icon-only"></span></summary><div class="accordion__content rich-text rich-text--contained"><p>There are no specific requirements to enter this qualification however all (potential) students (applicants) need to demonstrate the required (appropriate) level of language, literacy and numeracy skills and knowledge to undertake a qualification at this level.</p><p>A Language, Literacy, Numeracy and Digital Literacy (LLND) evaluation helps identify any areas where you may need additional support to help you achieve your goals</p></div></details> </div> </div>',
    apply_form = 'https://student-cdu.studylink.com/'
