    entry_requirements = '<div class="section--l section--narrow section rich-text elevator__target" data-elevator-title="Entry requirements" data-student-type="domestic" id="entry-requirements"> <div class="section__content"> <h2>Entry requirements</h2> <details class="accordion accordion--divided" data-once="webform-details-save" data-student-type="domestic"><summary class="accordion__toggle" data-once="webform-details-summary-save" id="accordion-admission-criteria--3"><h3> Admission criteria </h3><span class="button button--small button--icon-only"></span></summary><div class="accordion__content rich-text rich-text--contained"><p>Applicants must be 16 years old by the Census Date of the relevant admission period and have completed Year 10.</p></div></details> </div> </div>',
